from abc import ABC, abstractmethod

class Processor(ABC):
    @abstractmethod
    def process(self, rows): ...
    def __len__(self):
        return self._n

class Uppercase(Processor):
    def __init__(self):
        self._n = 0
    def process(self, rows):
        self._n = len(rows)
        return [r.upper() for r in rows]
    @property
    def processed(self):
        return self._n
    def __repr__(self):
        return f"Uppercase(processed={self._n})"

