import time, functools

def timed(fn):
    @functools.wraps(fn)
    def wrap(*a, **k):
        t = time.perf_counter()
        r = fn(*a, **k)
        print(f"{fn.__name__} finished, took_ms>=0: {(time.perf_counter() - t) * 1000 >= 0}")
        return r
    return wrap

class Timer:
    def __enter__(self):
        print("start")
        return self
    def __exit__(self, *exc):
        print("end")
        return False

@timed
def work(n):
    return sum(range(n))

print(work(1000))
with Timer():
    print("inside")

