import time
PAGES = {1: {"items": [1, 2], "next": 2}, 2: {"items": [3, 4], "next": 3}, 3: {"items": [5], "next": None}}
calls = {"n": 0}
def fetch(page):
    calls["n"] += 1
    if calls["n"] == 2:
        raise ConnectionError("temporary failure")
    return PAGES[page]

def fetch_retry(page, tries=3):
    for attempt in range(tries):
        try:
            return fetch(page)
        except ConnectionError:
            wait = 0.01 * 2 ** attempt
            print(f"retry page {page} after {wait}s")
            time.sleep(wait)
    raise RuntimeError("giving up")

page, items = 1, []
while page:
    data = fetch_retry(page)
    items += data["items"]
    page = data["next"]
print(items)

